// Aliases
DEVICONS.js = DEVICONS.javascript;
DEVICONS.ts = DEVICONS.typescript;
DEVICONS.node = DEVICONS.nodejs;
DEVICONS.golang = DEVICONS.go;
DEVICONS.postgresql = DEVICONS.postgres;
DEVICONS.pgsql = DEVICONS.postgres;
DEVICONS.py = DEVICONS.python;
DEVICONS['discord-bot'] = DEVICONS.discord;
DEVICONS['telegram-bot'] = DEVICONS.telegram;

DEVICONS.sh = DEVICONS.bash;
DEVICONS.shell = DEVICONS.bash;
DEVICONS.yml = DEVICONS.yaml;
DEVICONS.md = DEVICONS.markdown;
DEVICONS.html = DEVICONS.html5;
DEVICONS.css = DEVICONS.css3;
DEVICONS.scss = DEVICONS.sass;
DEVICONS.vite = DEVICONS.vitejs;
DEVICONS.jsx = DEVICONS.react;
DEVICONS.tsx = DEVICONS.react;

export function devicon(name, opts = {}) {
  const norm = (name || '').toLowerCase();
  const body = DEVICONS[norm];
  if (!body) return icon(name, opts);
  const size = opts.size || 18;
  const cls = ['devicon', `devicon-${norm}`, opts.cls || ''].filter(Boolean).join(' ');
  const style = opts.style ? ` style="${opts.style}"` : '';
  return `<svg class="${cls}" width="${size}" height="${size}" viewBox="0 0 128 128" role="img" aria-hidden="true"${style}>${body}</svg>`;
}

export function icon(name, opts = {}) {
  const norm = (name || '').toLowerCase();
    if (DEVICONS[norm]) {
      return devicon(norm, opts);
    }
    const body = P[name] || P.file;
    const size = opts.size || 16;
    const stroke = opts.stroke || 1.5;
    const cls = ['icon', `icon-${name}`, opts.cls || ''].filter(Boolean).join(' ');
    const style = opts.style ? ` style="${opts.style}"` : '';
    return `<svg class="${cls}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"${style}>${body}</svg>`;
  }

  export const ICON_NAMES = Object.keys(P).concat(Object.keys(DEVICONS));

  if (typeof window !== 'undefined') {
    window.icon = icon;
    window.devicon = devicon;
    window.DEVICONS = DEVICONS;
  }
